(()=>{
const oldDashboard=applyWarehouseDashboard;applyWarehouseDashboard=function(){oldDashboard();if(!isOpsRole()){const b=document.querySelector(".actions .primary");b.textContent="＋ 新建单据";b.onclick=()=>document.querySelector("dialog").showModal();return;}document.getElementById('stats').innerHTML=[['服务可用率','99.95','%','近24小时 · 示例'],['接口 P95 延迟','820','ms','超过500ms阈值'],['待处理告警','3','项','1项高优先级'],['同步积压','124','条','需排查消费链路']].map(v=>'<div class="stat"><div class="statlabel">'+v[0]+'</div><div class="number">'+v[1]+' <small>'+v[2]+'</small></div><div class="statfoot">'+v[3]+'</div></div>').join('');document.querySelector('.ai-suggestions').innerHTML=['服务巡检','接口诊断','日志排查','同步链路','变更检查'].map(x=>'<button onclick="suggest(\'请协助进行库存服务'+x+'，输出诊断依据和建议\')">'+x+'</button>').join('');promptBox.placeholder='描述库存服务问题，例如：排查接口超时、同步失败或消息积压…';document.querySelector('.actions .primary').textContent='＋ 新建运维会话';document.querySelector('.actions .primary').onclick=openNewConversation};
const oldConcerns=renderConcerns;renderConcerns=function(tab=0){if(!isOpsRole()){oldConcerns(tab);return}const r=document.getElementById('concerns');r.hidden=false;document.querySelector('.assistant-panel').hidden=true;r.innerHTML='<div class="concern-head"><h2>库存服务运行动态</h2><small>服务健康 / 接口同步 / 变更巡检 · 示例数据</small></div><div class="concern-panel"><table style="width:100%;text-align:left;border-spacing:16px"><thead><tr><th>服务 / 事件</th><th>当前指标</th><th>状态</th><th>操作</th></tr></thead><tbody>'+[['库存查询服务','P95 820ms','延迟告警','排查库存查询服务接口延迟升高，关联慢日志与数据库连接池'],['库存同步消费服务','积压124条','待诊断','分析库存同步消息积压，核查重试与幂等策略'],['库存服务发布验证','版本 v2.8.1','待巡检','执行库存服务发布后只读巡检，对比核心指标']].map(x=>'<tr><td>'+x[0]+'</td><td>'+x[1]+'</td><td>'+x[2]+'</td><td><button class="btn" data-ops-prompt="'+x[3]+'">AI诊断</button></td></tr>').join('')+'</tbody></table></div>';r.querySelectorAll('[data-ops-prompt]').forEach(b=>b.onclick=()=>{const q=b.dataset.opsPrompt;openNewConversation();suggest(q)})};
const oldRoleSessions=roleSessions;roleSessions=function(){if(!isOpsRole())return oldRoleSessions();if(!sessionRecords.some(x=>x.id==='ops-session-0')){sessionRecords=sessionRecords.filter(x=>!['inventory-ops-auto','inventory-ops-manual'].includes(x.id));[['库存查询接口超时排查','已发现接口P95延迟升高，建议关联慢查询与连接池指标。'],['库存同步消费积压诊断','待检查消费速率、失败重试及死信队列，未执行任何重试操作。'],['库存服务发布后巡检','请确认发布范围后检查错误率、延迟与依赖服务。']].forEach((x,i)=>sessionRecords.push({id:'ops-session-'+i,role:'inventory-ops',title:x[0],time:Date.now()-i*60000,messages:[{user:false,text:x[1]+' 当前为示例诊断。'}]}));saveSessionRecords()}return sessionRecords.filter(x=>x.role==='inventory-ops')};
const oldAgents=renderAgentOptions;renderAgentOptions=function(){if(!isOpsRole()){oldAgents();return}const q=document.getElementById('agent-search').value;document.getElementById('agent-options').innerHTML=OPS_GROUPS.filter(g=>(g.name+g.desc).includes(q)).map(g=>'<button class="picker-option" data-ops-agent="'+g.id+'"><strong>'+g.name+'</strong><small>'+g.desc+'</small></button>').join('');document.querySelectorAll('[data-ops-agent]').forEach(b=>b.onclick=()=>{selectedComposerAgent=b.dataset.opsAgent;document.getElementById('agent-toggle').textContent=OPS_GROUPS.find(g=>g.id===selectedComposerAgent).name+' ⌄';closeAgentMenu()})};
const oldSkills=renderSkillMenu;renderSkillMenu=function(){if(!isOpsRole()){oldSkills();return}const q=document.getElementById('skill-search').value;document.getElementById('installed-skills').innerHTML=OPS_GROUPS.flatMap(g=>g.skills.map(s=>({s,g}))).filter(x=>(x.s+x.g.name).includes(q)).map(x=>'<button class="skill-option" data-ops-skill="'+x.s+'"><span><strong>'+x.s+'</strong><small>'+x.g.name+'</small></span></button>').join('');document.querySelectorAll('[data-ops-skill]').forEach(b=>b.onclick=()=>{suggest('请协助'+b.dataset.opsSkill+'，仅诊断并输出建议，变更需我确认。');closeSkillMenu()})};
const oldSend=sendPrompt;sendPrompt=function(){if(!isOpsRole()){oldSend();return}const q=promptBox.value.trim();if(!q)return;addMessage(q,true);promptBox.value='';refreshSend();addMessage('库存服务运维诊断（示例）：\n1. 检查服务可用率、P95延迟、错误率与最近发布记录。\n2. 关联接口日志、数据库连接池、缓存命中率和消息消费积压，定位异常链路。\n3. 优先只读核查；重试补偿、重启、配置变更与回滚需审批及人工确认。\n建议：先核查库存查询接口慢请求与同步消费失败日志，再确定处置范围。当前未连接真实监控或执行任何运维操作。',false)};
const oldNew=openNewConversation;openNewConversation=function(){oldNew();if(!isOpsRole())return;document.getElementById('stats').hidden=true;document.getElementById('concerns').hidden=true;document.querySelector('.assistant-panel').hidden=false;document.getElementById('title').textContent='小伟，今天需要排查什么库存服务问题？';document.getElementById('subtitle').textContent='关联服务指标、接口日志与同步链路，让故障定位和处置更清晰。';document.getElementById('crumb').textContent='新建会话';document.getElementById('agent-toggle').textContent='选择运维智能体 ⌄'};
const oldModule=setModule;setModule=function(name){oldModule(name);if(isOpsRole()&&['工作台','业务概览'].includes(name)){document.getElementById('title').textContent='库存服务，稳定在线。';document.getElementById('subtitle').textContent='ERP库存服务运行概况：关注接口延迟、同步异常、告警处置与变更验证。所有指标为示例。'}};
})();

function runInventoryCollaboration(result,choice){
 result.dataset.processing='true';
 const d=document.createElement('dialog');d.className='ops-progress-dialog';d.setAttribute('aria-labelledby','ops-progress-title');
 d.innerHTML='<h2 id="ops-progress-title">正在处理库存数据差异</h2><p class="ops-progress-status" role="status">正在核查差异与准备推送…</p><progress max="100" value="0" aria-label="数据重新推送进度"></progress><p class="ops-progress-percent">0%</p><small>演示流程 · 未操作真实ERP/WMS或发送真实通知</small><div class="actions"><button class="btn primary" id="notify-xiaoqin" hidden>进度通知小琴</button></div>';
 document.body.append(d);d.showModal();d.addEventListener('cancel',e=>e.preventDefault());
 let value=0;const timer=setInterval(()=>{value=Math.min(100,value+5);d.querySelector('progress').value=value;d.querySelector('.ops-progress-percent').textContent=value+'%';d.querySelector('.ops-progress-status').textContent=value<35?'正在核查差异与准备推送…':value<75?'正在重新推送库存数据…':'正在复核推送结果…';if(value===100){clearInterval(timer);d.querySelector('h2').textContent='数据已重新推送';d.querySelector('.ops-progress-status').textContent='所选方案处理已完成，请通知小琴跟进结果。';const notify=d.querySelector('#notify-xiaoqin');notify.hidden=false;notify.focus();}},140);
 d.querySelector('#notify-xiaoqin').onclick=()=>{try{const key='erp-ops-activity-tasks';const list=JSON.parse(localStorage.getItem(key))||[];const task=list.find(t=>t.id==='ERP-WMS-DAILY');if(task){task.state='done';task.resolution=choice.querySelector('strong').textContent;task.notified='小琴';localStorage.setItem(key,JSON.stringify(list))}}catch(e){d.querySelector('.ops-progress-status').textContent='任务状态保存失败，请重试。';return}result.dataset.processing='false';result.dataset.completed='true';result.querySelector('.inventory-chat-success').textContent='✓ 任务已完成 · 已通知小琴（演示）';d.querySelector('h2').textContent='任务已完成';d.querySelector('.ops-progress-status').textContent='进度已通知小琴（演示），协同任务已归入已完成。';const b=d.querySelector('#notify-xiaoqin');b.textContent='完成';b.onclick=()=>{d.close();d.remove()};document.querySelector('#activity-view iframe')?.contentWindow.location.reload();};
}
